AK_LANG="en"
AK_ASSUME_YES=0
AK_LOG_FILE="/dev/null"
AK_TTY=0
AK_STEP_NO=0
AK_STEP_TOTAL=0
AK_SPIN_PID=""

ak_init_term() {
    if [[ -t 1 && -z ${NO_COLOR:-} && ${TERM:-dumb} != "dumb" ]]; then
        AK_TTY=1
        C_RESET=$'\e[0m'; C_BOLD=$'\e[1m'; C_DIM=$'\e[2m'
        C_RED=$'\e[31m'; C_GREEN=$'\e[32m'; C_YELLOW=$'\e[33m'
        C_BLUE=$'\e[34m'; C_CYAN=$'\e[36m'; C_GREY=$'\e[90m'
        C_ERASE=$'\r\e[2K'
    else
        AK_TTY=0
        C_RESET=""; C_BOLD=""; C_DIM=""
        C_RED=""; C_GREEN=""; C_YELLOW=""
        C_BLUE=""; C_CYAN=""; C_GREY=""
        C_ERASE=$'\n'
    fi
    if [[ ${LANG:-}${LC_ALL:-} == *[Uu][Tt][Ff]* ]]; then
        G_OK="✔"; G_ERR="✖"; G_WARN="!"; G_INFO="•"; G_ARROW="→"; G_LINE="─"
        AK_SPIN_FRAMES=(⠋ ⠙ ⠹ ⠸ ⠼ ⠴ ⠦ ⠧ ⠇ ⠏)
    else
        G_OK="+"; G_ERR="x"; G_WARN="!"; G_INFO="*"; G_ARROW=">"; G_LINE="-"
        AK_SPIN_FRAMES=('|' '/' '-' '\')
    fi
}

ak_log_init() {
    AK_LOG_FILE="$1"
    : >"$AK_LOG_FILE" 2>/dev/null || AK_LOG_FILE="/dev/null"
    chmod 600 "$AK_LOG_FILE" 2>/dev/null || true
    ak_log "session started, common.sh $AK_COMMON_VERSION"
}

ak_log() {
    printf '%s | %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*" >>"$AK_LOG_FILE" 2>/dev/null || true
}

ak_lang_autodetect() {
    local src="${AK_FORCE_LANG:-${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}}"
    case "${src,,}" in
        pt_br*|pt-br*)  echo "pt_BR" ;;
        pt*)            echo "pt" ;;
        de*)            echo "de" ;;
        ru*|uk*|be*)    echo "ru" ;;
        fr*)            echo "fr" ;;
        zh*)            echo "zh" ;;
        ko*)            echo "ko" ;;
        ja*)            echo "ja" ;;
        tr*)            echo "tr" ;;
        *)              echo "en" ;;
    esac
}

ak_set_lang() {
    local code="$1"
    local found=0 l
    for l in "${AK_LANGS[@]}"; do [[ $l == "$code" ]] && found=1 && break; done
    [[ $found -eq 1 ]] || code="en"
    AK_LANG="$code"
}

t() {
    local key="$1"; shift
    local -n _cat="AK_MSG_${AK_LANG}"
    local s="${_cat[$key]:-}"
    if [[ -z $s ]]; then
        local -n _en="AK_MSG_en"
        s="${_en[$key]:-$key}"
    fi
    # shellcheck disable=SC2059
    printf -- "$s" "$@"
}

ui_rule() {
    local w="${COLUMNS:-64}"
    (( w > 72 )) && w=72
    local line=""
    local i
    for (( i = 0; i < w; i++ )); do line+="$G_LINE"; done
    printf '%s%s%s\n' "$C_GREY" "$line" "$C_RESET"
}

ui_banner() {
    printf '\n'
    ui_rule
    printf '  %s%s%s\n' "$C_BOLD$C_CYAN" "$1" "$C_RESET"
    [[ -n ${2:-} ]] && printf '  %s%s%s\n' "$C_GREY" "$2" "$C_RESET"
    ui_rule
    printf '\n'
}

ui_section() {
    printf '\n%s%s %s%s\n' "$C_BOLD" "$G_ARROW" "$1" "$C_RESET"
}

ui_ok()     { printf '  %s%s%s %s\n' "$C_GREEN" "$G_OK" "$C_RESET" "$1"; ak_log "OK   $1"; }
ui_info()   { printf '  %s%s%s %s\n' "$C_CYAN"  "$G_INFO" "$C_RESET" "$1"; ak_log "INFO $1"; }
ui_warn()   { printf '  %s%s %s%s\n' "$C_YELLOW" "$G_WARN" "$1" "$C_RESET"; ak_log "WARN $1"; }
ui_err()    { printf '  %s%s %s%s\n' "$C_RED" "$G_ERR" "$1" "$C_RESET" >&2; ak_log "ERR  $1"; }
ui_plain()  { printf '  %s\n' "$1"; }

ak_width() {
    local LC_ALL=C
    local s="$1"
    local len i w b0 b1 b2 cp
    len=${#s}; i=0; w=0
    while (( i < len )); do
        printf -v b0 '%d' "'${s:i:1}"
        (( b0 < 0 )) && b0=$(( b0 + 256 ))
        if (( b0 < 0x80 )); then
            w=$(( w + 1 )); i=$(( i + 1 ))
        elif (( b0 < 0xE0 )); then
            w=$(( w + 1 )); i=$(( i + 2 ))
        elif (( b0 < 0xF0 )); then
            printf -v b1 '%d' "'${s:i+1:1}"; (( b1 < 0 )) && b1=$(( b1 + 256 ))
            printf -v b2 '%d' "'${s:i+2:1}"; (( b2 < 0 )) && b2=$(( b2 + 256 ))
            cp=$(( ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F) ))
            if (( (cp >= 0x1100 && cp <= 0x115F) || (cp >= 0x2E80 && cp <= 0x303E) || \
                  (cp >= 0x3041 && cp <= 0x33FF) || (cp >= 0x3400 && cp <= 0x4DBF) || \
                  (cp >= 0x4E00 && cp <= 0x9FFF) || (cp >= 0xA000 && cp <= 0xA4CF) || \
                  (cp >= 0xAC00 && cp <= 0xD7A3) || (cp >= 0xF900 && cp <= 0xFAFF) || \
                  (cp >= 0xFE30 && cp <= 0xFE6F) || (cp >= 0xFF00 && cp <= 0xFF60) || \
                  (cp >= 0xFFE0 && cp <= 0xFFE6) )); then
                w=$(( w + 2 ))
            else
                w=$(( w + 1 ))
            fi
            i=$(( i + 3 ))
        else
            w=$(( w + 2 )); i=$(( i + 4 ))
        fi
    done
    printf '%d' "$w"
}

ak_pad() {
    local text="$1" target="$2" w pad=""
    w=$(ak_width "$text")
    while (( w < target )); do pad+=" "; w=$(( w + 1 )); done
    printf '%s%s' "$text" "$pad"
}

AK_KV_WIDTH=30

ui_kv() {
    printf '  %s %s%s%s\n' "$(ak_pad "$1" "$AK_KV_WIDTH")" "$C_BOLD" "$2" "$C_RESET"
}

ak_spin_start() {
    [[ $AK_TTY -eq 1 ]] || return 0
    local msg="$1"
    (
        local i=0
        while :; do
            printf '%s  %s%s%s %s' "$C_ERASE" "$C_CYAN" "${AK_SPIN_FRAMES[i]}" "$C_RESET" "$msg"
            i=$(( (i + 1) % ${#AK_SPIN_FRAMES[@]} ))
            sleep 0.12
        done
    ) &
    AK_SPIN_PID=$!
}

ak_spin_stop() {
    [[ -n $AK_SPIN_PID ]] || return 0
    kill "$AK_SPIN_PID" >/dev/null 2>&1 || true
    wait "$AK_SPIN_PID" 2>/dev/null || true
    AK_SPIN_PID=""
    [[ $AK_TTY -eq 1 ]] && printf '%s' "$C_ERASE"
    return 0
}

ui_step_start() {
    AK_STEP_NO=$(( AK_STEP_NO + 1 ))
    AK_STEP_LABEL="$1"
    ak_log "STEP $AK_STEP_NO/$AK_STEP_TOTAL $1"
    if [[ $AK_TTY -eq 1 ]]; then
        ak_spin_start "$(printf '%s[%02d/%02d]%s %s' "$C_GREY" "$AK_STEP_NO" "$AK_STEP_TOTAL" "$C_RESET" "$1")"
    else
        printf '  [%02d/%02d] %s\n' "$AK_STEP_NO" "$AK_STEP_TOTAL" "$1"
    fi
}

ui_step_end() {
    local status="$1" note="${2:-}"
    ak_spin_stop
    local tag
    case "$status" in
        ok)   tag="${C_GREEN}${G_OK} $(t ok)${C_RESET}" ;;
        fail) tag="${C_RED}${G_ERR} $(t failed)${C_RESET}" ;;
        skip) tag="${C_GREY}${G_INFO} $(t skipped)${C_RESET}" ;;
        warn) tag="${C_YELLOW}${G_WARN} $(t warn)${C_RESET}" ;;
    esac
    if [[ $AK_TTY -eq 1 ]]; then
        printf '  %s[%02d/%02d]%s %s  %s\n' "$C_GREY" "$AK_STEP_NO" "$AK_STEP_TOTAL" "$C_RESET" "$AK_STEP_LABEL" "$tag"
    else
        printf '          %s\n' "$tag"
    fi
    [[ -n $note ]] && ui_plain "$C_GREY$note$C_RESET"
    ak_log "     -> $status $note"
    return 0
}

ak_read() {
    local __akr_var="$1" __akr_prompt="$2" __akr_silent="${3:-}"
    local __akr_reply="" __akr_rc=0 __akr_fd

    if [[ -t 0 ]]; then
        if [[ $__akr_silent == "silent" ]]; then
            read -r -s -p "$__akr_prompt" __akr_reply || __akr_rc=$?
            printf '\n'
        else
            read -r -p "$__akr_prompt" __akr_reply || __akr_rc=$?
        fi
    else
        exec {__akr_fd}</dev/tty 2>/dev/null || return 1
        if [[ $__akr_silent == "silent" ]]; then
            read -r -s -p "$__akr_prompt" __akr_reply <&"$__akr_fd" || __akr_rc=$?
            printf '\n'
        else
            read -r -p "$__akr_prompt" __akr_reply <&"$__akr_fd" || __akr_rc=$?
        fi
        exec {__akr_fd}<&-
    fi

    (( __akr_rc == 0 )) || return 1
    printf -v "$__akr_var" '%s' "$__akr_reply"
    return 0
}

ak_interactive() {
    local tty_fd
    [[ -t 0 ]] && return 0
    exec {tty_fd}</dev/tty 2>/dev/null || return 1
    exec {tty_fd}<&-
    return 0
}

ui_confirm() {
    local __akc_question="$1" __akc_default="${2:-y}" __akc_reply __akc_hint
    if [[ $AK_ASSUME_YES -eq 1 ]]; then
        [[ $__akc_default == y ]] && return 0 || return 1
    fi
    if [[ $__akc_default == y ]]; then __akc_hint="[Y/n]"; else __akc_hint="[y/N]"; fi
    while :; do
        if ! ak_read __akc_reply "  $C_BOLD$__akc_question$C_RESET $C_GREY$__akc_hint$C_RESET "; then
            [[ $__akc_default == y ]] && return 0 || return 1
        fi
        __akc_reply="${__akc_reply,,}"
        if [[ -z $__akc_reply ]]; then
            [[ $__akc_default == y ]] && return 0 || return 1
        fi
        case "$__akc_reply" in
            y|yes|"$(t yes_key)") return 0 ;;
            n|no|"$(t no_key)")   return 1 ;;
            *) ui_warn "$(t invalid_choice)" ;;
        esac
    done
}

ui_menu() {
    local __akm_var="$1" __akm_prompt="$2"; shift 2
    local __akm_options=("$@") __akm_reply __akm_i
    printf '\n'
    for __akm_i in "${!__akm_options[@]}"; do
        printf '    %s[%d]%s %s\n' "$C_CYAN" "$((__akm_i + 1))" "$C_RESET" "${__akm_options[$__akm_i]}"
    done
    printf '\n'
    while :; do
        if ! ak_read __akm_reply "  $C_BOLD$__akm_prompt$C_RESET $C_GREY[1-${#__akm_options[@]}]$C_RESET "; then
            printf -v "$__akm_var" '%s' "1"
            return 0
        fi
        if [[ $__akm_reply =~ ^[0-9]+$ ]] && (( __akm_reply >= 1 && __akm_reply <= ${#__akm_options[@]} )); then
            printf -v "$__akm_var" '%s' "$__akm_reply"
            return 0
        fi
        ui_warn "$(t invalid_choice)"
    done
}

ui_language_menu() {
    local __akl_choice=1 __akl_names=() __akl_code
    for __akl_code in "${AK_LANGS[@]}"; do __akl_names+=("${AK_LANG_NAMES[$__akl_code]}"); done
    ui_banner "$(t lang_title)" "Language · Sprache · Язык · 语言 · 言語 · 언어"
    ui_menu __akl_choice "$(t lang_prompt)" "${__akl_names[@]}"
    ak_set_lang "${AK_LANGS[$((__akl_choice - 1))]}"
    ak_log "language set to $AK_LANG"
}

ak_have() { command -v "$1" >/dev/null 2>&1; }

ak_is_ipv4() {
    local ip="$1" o
    [[ $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    IFS='.' read -r -a o <<<"$ip"
    for x in "${o[@]}"; do (( x >= 0 && x <= 255 )) || return 1; done
    return 0
}

ak_is_private_ip() {
    local ip="$1"
    [[ $ip =~ ^10\. ]] && return 0
    [[ $ip =~ ^192\.168\. ]] && return 0
    [[ $ip =~ ^172\.(1[6-9]|2[0-9]|3[01])\. ]] && return 0
    [[ $ip =~ ^127\. ]] && return 0
    [[ $ip =~ ^100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\. ]] && return 0
    return 1
}

ak_sql_escape() { printf '%s' "${1//\'/\'\'}"; }

ak_conf_save() {
    umask 077
    cat >"$AK_CONF_FILE" <<EOF
AK_INSTALL_DIR="$1"
AK_LANG="$2"
AK_SERVER_IP="$3"
EOF
}

ak_conf_load() {
    if [[ -r $AK_CONF_FILE ]]; then
        # shellcheck disable=SC1090
        . "$AK_CONF_FILE"
        [[ -n ${AK_LANG:-} ]] && ak_set_lang "$AK_LANG"
    fi
    return 0
}

ak_find_server_pid() {
    local exe="$1/$2/$2" proc link
    for proc in /proc/[0-9]*; do
        link=$(readlink -f "$proc/exe" 2>/dev/null) || continue
        if [[ $link == "$exe" ]]; then
            printf '%s' "${proc#/proc/}"
            return 0
        fi
    done
    return 1
}

ak_server_pid() {
    local dir="$1" name="$2" file="$3" pid
    if [[ -r $file ]]; then
        pid=$(<"$file")
        if [[ $pid =~ ^[0-9]+$ && -d "/proc/$pid" && $(readlink -f "/proc/$pid/exe" 2>/dev/null) == "$dir/$name/$name" ]]; then
            printf '%s' "$pid"
            return 0
        fi
    fi
    ak_find_server_pid "$dir" "$name"
}

ak_resolve_install_dir() {
    local dir="${AK_INSTALL_DIR:-}"
    [[ -n ${1:-} ]] && dir="$1"
    [[ -z $dir ]] && dir="$AK_DEFAULT_DIR"
    printf '%s' "$dir"
}

ak_init_term
ak_set_lang "$(ak_lang_autodetect)"
